function dailyGuidePanel(d){const g=d.dailyGuide;if(!g)return '';return '<section class="panel daily-guide"><div class="eyebrow">ESTUDO GUIADO DE HOJE</div><h2>Seu roteiro de estudo</h2><p class="muted">'+esc(g.notice||'Plano adaptativo para hoje.')+'</p><div class="guide-blocks">'+(g.blocks||[]).map(b=>'<div class="guide-block"><div class="row between"><strong>'+esc(b.focus)+'</strong><span class="badge">'+b.minutes+' min</span></div><p>'+esc(b.title)+'</p>'+(b.estimatedPages?'<span class="small muted">Estimativa: '+b.estimatedPages+' páginas</span>':'')+'</div>').join('')+'</div></section>';}
const $=selector=>document.querySelector(selector);
const repair=value=>String(value??'').replaceAll('P?gina','P�gina').replaceAll('n?o','n�o').replaceAll('dispon?vel','dispon�vel').replaceAll('extra??o','extra��o').replaceAll('valida??o','valida��o').replaceAll('autoriza??o','autoriza��o').replaceAll('permiss?es','permiss�es').replaceAll('p?ginas','p�ginas').replaceAll('informa??o','informa��o');
const esc=value=>repair(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
