    if(action==='tts-start'){speechSynthesis.cancel();ttsUtterance=new SpeechSynthesisUtterance($('#lesson-text').innerText);ttsUtterance.lang='pt-BR';ttsUtterance.rate=1;ttsUtterance.pitch=1;const voices=speechSynthesis.getVoices(),voice=voices.find(v=>v.lang?.toLowerCase().startsWith('pt-br'))||voices.find(v=>v.lang?.toLowerCase().startsWith('pt'));if(voice)ttsUtterance.voice=voice;ttsUtterance.onend=()=>{ttsUtterance=null;toast('Narra��o conclu�da.');};ttsUtterance.onerror=()=>toast('N�o foi poss�vel narrar este conte�do.',true);speechSynthesis.speak(ttsUtterance);return;}
