    if(action==='finish-simulation'){if(await confirmAction('Finalizar simula��o','As respostas registradas ser�o preservadas. Perguntas restantes ficar�o sem avalia��o.','Finalizar')){await api('/api/simulations/finish',{method:'POST',data:{id:state.simulation.id}});state.simulation=await api('/api/simulations/'+state.simulation.id);await refresh();}return;}
    if(action==='open-document'||action==='open-source')return openDocument(el.dataset.id,Number(el.dataset.page)||1);
    if(action==='source-by-id'){for(const d of state.data.documents){const doc=await api('/api/documents/'+d.id);const chunk=doc.chunks.find(c=>c.id===el.dataset.id);if(chunk)return openDocument(d.id,chunk.page);}throw new Error('Fonte indispon�vel para esta conta.');}
    if(action==='document-metadata'){const doc=state.data.documents.find(d=>d.id===el.dataset.id);modal('Metadados e disponibilidade',`<form id="metadata-form"><label>T�tulo<input name="title" required value="${esc(doc.title)}"></label><label>Autor<input name="author" value="${esc(doc.author)}"></label><label>Edi��o<input name="edition" value="${esc(doc.edition)}"></label><label>Categoria<input name="category" value="${esc(doc.category)}"></label><label>Descri��o<textarea name="description">${esc(doc.description)}</textarea></label><label class="check"><input type="checkbox" name="shared" ${doc.shared?'checked':''}>Compartilhar como fonte curricular com as contas autorizadas</label><button class="primary">Salvar disponibilidade</button></form>`);$('#metadata-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const fd=new FormData(e.currentTarget);await api('/api/admin/documents/metadata',{method:'POST',data:{...Object.fromEntries(fd),id:doc.id,shared:fd.has('shared')}});closeModal();await refresh('Documento atualizado.');});};return;}
    if(action==='upload-document')return uploadDocument();
    if(action==='process-document'){el.disabled=true;await api('/api/admin/documents/process',{method:'POST',data:{id:el.dataset.id}});return refresh('Extra��o conclu�da. Confira as p�ginas antes de validar.');}
    if(action==='validate-document'){if(await confirmAction('Validar extra��o','Conferi a pagina��o, os trechos e as p�ginas sem texto com o PDF original. Confirmar disponibiliza os fragmentos para recupera��o.','Confirmar confer�ncia')){await api('/api/admin/documents/validate',{method:'POST',data:{id:el.dataset.id,confirmed:true}});await refresh('Documento validado.');}return;}
    if(action==='index-document'){el.disabled=true;await api('/api/admin/documents/index',{method:'POST',data:{id:el.dataset.id}});return refresh('Indexa��o sem�ntica conclu�da.');}
    if(action==='delete-document'){if(await confirmAction('Remover documento','O PDF e seus fragmentos ser�o exclu�dos. Materiais publicados que dependem dele precisam ser arquivadas antes.','Remover')){await api('/api/admin/documents/delete',{method:'POST',data:{id:el.dataset.id}});await refresh('Documento removido.');}return;}
    if(action==='import-pages'){const id=el.dataset.id;modal('Importar extra��o revis�vel',`<p class="small muted">Use o n�mero f�sico da p�gina do PDF. N�o atribua texto a uma p�gina sem conferi-lo.</p><form id="pages-form"><label>Lista de p�ginas (JSON)<textarea name="pages" class="code" required>[{"page":1,"section":"T�tulo da se��o","text":"Texto extra�do desta p�gina"}]</textarea></label><button class="primary">Importar para confer�ncia</button></form>`);$('#pages-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/documents/pages',{method:'POST',data:{id,pages:JSON.parse(new FormData(e.currentTarget).get('pages'))}});closeModal();await refresh('P�ginas importadas; valide a extra��o ap�s conferir.');});};return;}
    if(action==='edit-lesson')return lessonEditor(el.dataset.id);
    if(action==='edit-question')return questionEditor(el.dataset.id);
    if(action==='lesson-status'){await api('/api/admin/lessons/transition',{method:'POST',data:{ids:[el.dataset.id],status:el.dataset.status}});return refresh('Revis�o registrada.');}
    if(action==='publish-batch'){const ids=[...document.querySelectorAll('.batch-lesson:checked')].map(x=>x.value);await api('/api/admin/lessons/transition',{method:'POST',data:{ids,status:'published'}});return refresh('Materiais aprovados publicados.');}
    if(action==='lesson-versions'){const versions=state.data.admin.versions.filter(x=>x.lessonId===el.dataset.id);modal('Hist�rico de vers�es',versions.length?versions.slice().reverse().map(v=>`<details class="discipline"><summary>Vers�o ${v.version} � ${date(v.createdAt)}</summary><pre>${esc(JSON.stringify(v.snapshot,null,2))}</pre></details>`).join(''):empty('Nenhuma vers�o anterior','As pr�ximas edi��es e transi��es ser�o registradas.'));return;}
    if(action==='question-status'){await api('/api/admin/questions/publish',{method:'POST',data:{id:el.dataset.id,status:el.dataset.status}});return refresh('Status da quest�o atualizado.');}
    if(action==='import-questions'){modal('Importa��o de quest�es',`<p class="small muted">At� 200 por lote. Texto original preservado. Use os IDs de disciplina mostrados no curr�culo e informe source para perguntas reais.</p><details><summary>Exemplo de estrutura (n�o ser� importado automaticamente)</summary><pre>${esc(JSON.stringify([{text:'Insira a pergunta original',disciplineId:'sistematica-1',type:'discursive',origin:'real',source:'Identifica��o do banco fornecido',difficulty:2,bibleRequired:true,essential:false}],null,2))}</pre></details><form id="questions-import"><label>Lista JSON<textarea name="questions" class="code" required></textarea></label><button class="primary">Importar como rascunhos</button></form>`);$('#questions-import').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/questions',{method:'POST',data:{questions:JSON.parse(new FormData(e.currentTarget).get('questions'))}});closeModal();await refresh('Quest�es importadas para revis�o.');});};return;}
    if(action==='edit-curriculum'){const table=el.dataset.table,row=state.data[table==='curriculum'?'axes':table].find(x=>x.id===el.dataset.id);modal('Editar estrutura',`<p class="small muted">ID: ${esc(row.id)}</p><form id="curriculum-editor"><label>T�tulo<input name="title" required value="${esc(row.title)}"></label><button class="primary">Salvar</button></form>`);$('#curriculum-editor').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{await api('/api/admin/curriculum',{method:'POST',data:{...row,table,title:new FormData(e.currentTarget).get('title')}});closeModal();await refresh('Estrutura atualizada.');});};return;}
    if(action==='generate-content'){modal('Gerar rascunhos com IA',`<p class="small muted">Cada assunto gera uma material de estudo. Os materiais entram como Gerado por IA e precisam de revis�o e aprova��o individuais.</p><form id="generate-form"><label>Disciplina<select name="disciplineId">${options(state.data.disciplines)}</select></label><label>M�dulo<select name="moduleId"><option value="">Selecionar depois</option>${options(state.data.modules)}</select></label><label>Assuntos (um por linha, at� 5)<textarea name="subjects" required></textarea></label><button class="primary">Gerar para revis�o</button><p id="generate-progress" class="small muted"></p></form>`);$('#generate-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,async()=>{const fd=new FormData(e.currentTarget),subjects=String(fd.get('subjects')).split('\n').filter(x=>x.trim());if(subjects.length>5)throw new Error('Use at� 5 assuntos por lote.');for(let i=0;i<subjects.length;i++){$('#generate-progress').textContent=`Gerando ${i+1} de ${subjects.length}.`;await api('/api/admin/generate',{method:'POST',data:{disciplineId:fd.get('disciplineId'),moduleId:fd.get('moduleId')||null,subject:subjects[i]}});}closeModal();await refresh('Rascunhos gerados. Nenhum material foi publicado.');});};return;}
    if(action==='load-models'){el.disabled=true;const result=await api('/api/admin/ai/models');$('#ai-models').innerHTML=result.models.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');toast(`${result.models.length} modelos dispon�veis para a conta autorizada.`);return;}
    if(action==='test-ai'){el.disabled=true;const r=await api('/api/admin/ai/test',{method:'POST',data:{}});toast(r.ok?'Conex�o verificada.':'O provedor retornou uma resposta inesperada.',!r.ok);return;}
