    if(action==='delete-entry'){if(await confirmAction('Excluir registro','Esta entrada complementar ser� removida.','Excluir')){state.journey.entries=state.journey.entries.filter(x=>x.id!==el.dataset.id);await api('/api/journey',{method:'POST',data:state.journey});await loadJourney();}return;}
