function questionForm(q,diagnostic=false){const prompt=q.text||q.prompt||q.question||'Enunciado n�o informado';const origin=q.origin||((q.provenanceKind||'').includes('real')?'real':'complementary');return `<form class="question" data-question-id="${q.id}" data-diagnostic="${diagnostic}"><div class="row between">${badge(q.type==='discursive'?'Discursiva':q.type==='matching'?'Associa��o':'Objetiva')}${badge(origin==='real'?'Quest�o real':'Complementar')}</div>${q.axisId||q.discipline?`<p class="small muted question-meta">${esc(q.axisId||'')}${q.discipline?` � ${esc(q.discipline)}`:''}</p>`:''}<h3 style="margin-top:15px">${esc(prompt)}</h3>${q.type==='discursive'?'<textarea name="answer" required minlength="5" maxlength="15000" aria-label="Sua resposta"></textarea>':q.type==='matching'?`<label>Associa��o (JSON)<textarea class="code" name="answer" required placeholder='{"A":"1","B":"2"}'></textarea></label>`:(q.type==='true_false'?['Verdadeiro','Falso']:q.options||[]).map((o,i)=>`<label class="option"><input type="radio" name="answer" value="${esc(q.type==='true_false'?String(i===0):o)}" required><span>${esc(o)}</span></label>`).join('')}${diagnostic?'':`<button class="primary">Salvar resposta</button>`}<div class="answer-feedback" aria-live="polite"></div></form>`;}

